"""Character transliterations measured through the command's text interface.

Characters without an ASCII representation are omitted.  Transliteration is
character-wise: combining marks and joiners can therefore disappear without
changing the representation of their neighbors.
"""
import json
import pkgutil

_table = None


def to_ascii(text):
    global _table
    if text.isascii():
        return text
    if _table is None:
        _table = json.loads(pkgutil.get_data('rnr', 'ascii-map.json'))
    return ''.join(c if ord(c) < 128 else _table.get(str(ord(c)), '') for c in text)
EOF
