"""Command-line parsing and user-facing help."""
import os
import sys
from dataclasses import dataclass, field

ROOT_DESCRIPTION = ('RnR is a command-line tool to rename multiple files and directories that\n'
                    'supports regular expressions\n\n')
DESCRIPTIONS = {
    'regex': 'Rename files and directories using a regular expression',
    'from-file': 'Read operations from a dump file',
    'to-ascii': 'Replace file name UTF-8 chars with ASCII chars representation',
}
POSITIONALS = {
    'regex': ['<EXPRESSION>', '<REPLACEMENT>', '<PATH(S)>...'],
    'from-file': ['<DUMPFILE>'],
    'to-ascii': ['<PATH(S)>...'],
}
# name, short spelling, value placeholder, help text, choice values
COMMON = [
    ('dry-run', 'n', None, 'Only show what would be done (default mode)', None),
    ('force', 'f', None, 'Make actual changes to files', None),
    ('backup', 'b', None, 'Generate file backups before renaming', None),
    ('silent', 's', None, 'Do not print any information', None),
    ('color', None, 'COLOR', 'Set color output mode [default: auto] [possible values: always, never, auto]', ['always', 'never', 'auto']),
    ('dump', None, None, 'Force dumping operations into a file even in dry-run mode', None),
    ('dump-prefix', None, 'DUMP_PREFIX', 'Set the dump file prefix [default: rnr-]', None),
    ('no-dump', None, None, 'Do not dump operations into a file', None),
]
REGEX = [
    ('replace-limit', 'l', 'LIMIT', 'Limit of replacements, all matches if set to 0', None),
    ('replace-transform', 't', 'REPLACE_TRANSFORM', 'Apply a transformation to replacements including captured groups [possible values: upper, lower, ascii]', ['upper', 'lower', 'ascii']),
]
WALK = [
    ('include-dirs', 'D', None, 'Rename matching directories', None),
    ('recursive', 'r', None, 'Recursive mode', None),
    ('max-depth', 'd', 'LEVEL', 'Set max depth in recursive mode', None),
    ('hidden', 'x', None, 'Include hidden files and directories', None),
]
HELP = ('help', 'h', None, 'Print help', None)
CONFLICTS = {
    'dry-run': {'force'}, 'force': {'dry-run'},
    'dump': {'no-dump'}, 'dump-prefix': {'no-dump'},
    'no-dump': {'dump', 'dump-prefix'},
}


@dataclass
class Options:
    command: str
    positionals: list = field(default_factory=list)
    values: dict = field(default_factory=lambda: {'color': 'auto', 'dump-prefix': 'rnr-', 'replace-limit': 1})
    seen: list = field(default_factory=list)

    def get(self, name, default=False):
        return self.values.get(name, default)


def option_list(command):
    if command == 'regex':
        return COMMON + REGEX + WALK + [HELP]
    if command == 'to-ascii':
        return COMMON + WALK + [HELP]
    return COMMON + [('undo', 'u', None, 'Undo the operations from the dump file', None), HELP]


def label(option):
    return '--' + option[0] + ((' <' + option[2] + '>') if option[2] else '')


def usage(program, command=None, specific=None):
    if command is None:
        return f'Usage: {program} <COMMAND>'
    opts = '[OPTIONS]' if specific is None else ' '.join(specific)
    return ' '.join(x for x in [f'Usage: {program} {command}', opts, ' '.join(POSITIONALS[command])] if x)


def help_text(program, command=None):
    if command is None:
        return (ROOT_DESCRIPTION + '\n' + usage(program) + '\n\nCommands:\n'
                '  regex      Rename files and directories using a regular expression\n'
                '  from-file  Read operations from a dump file\n'
                '  to-ascii   Replace file name UTF-8 chars with ASCII chars representation\n'
                '  help       Print this message or the help of the given subcommand(s)\n\n'
                'Options:\n'
                '  -h, --help     Print help\n'
                '  -V, --version  Print version\n')
    text = DESCRIPTIONS[command] + '\n\n' + usage(program, command) + '\n\nArguments:\n'
    if command == 'regex':
        text += ('  <EXPRESSION>   Expression to match (can be a regex)\n'
                 '  <REPLACEMENT>  Expression replacement (use single quotes for capture groups)\n'
                 '  <PATH(S)>...   Target paths\n')
    elif command == 'from-file':
        text += '  <DUMPFILE>  \n'
    else:
        text += '  <PATH(S)>...  Target paths\n'
    text += '\nOptions:\n'
    for option in option_list(command):
        name, short, val, description, _ = option
        spelling = ('  -' + short + ', ' if short else '      ') + '--' + name
        if val:
            spelling += ' <' + val + '>'
        if command == 'regex':
            text += spelling + '\n          ' + description + '\n'
        else:
            text += spelling.ljust(34) + description + '\n'
    return text


def emit_help(program, command=None, code=0):
    (sys.stdout if code == 0 else sys.stderr).write(help_text(program, command))
    raise SystemExit(code)


def failure(message, use=None, tip=None, detail=None):
    result = 'error: ' + message + '\n'
    if detail:
        result += detail + '\n'
    if tip:
        result += '\n' + tip + '\n'
    if use:
        result += '\n' + use + '\n'
    result += "\nFor more information, try '--help'.\n"
    sys.stderr.write(result)
    raise SystemExit(2)


def similarity(a, b):
    """Jaro's matching window with a short common-prefix bonus."""
    if a == b:
        return 1.0
    win = max(len(a), len(b)) // 2 - 1
    win = max(0, win)
    am, bm = [False] * len(a), [False] * len(b)
    for i, c in enumerate(a):
        for j in range(max(0, i-win), min(len(b), i+win+1)):
            if not bm[j] and c == b[j]:
                am[i] = bm[j] = True
                break
    count = sum(am)
    if not count:
        return 0.0
    x = [a[i] for i in range(len(a)) if am[i]]
    y = [b[i] for i in range(len(b)) if bm[i]]
    transpositions = sum(c != d for c, d in zip(x, y)) / 2
    score = (count/len(a) + count/len(b) + (count-transpositions)/count) / 3
    prefix = 0
    for c, d in zip(a[:4], b[:4]):
        if c != d:
            break
        prefix += 1
    return score + prefix * 0.1 * (1-score)


def suggest(word, possibilities):
    scores = [(similarity(word, p), p) for p in possibilities]
    return max(scores)[1] if scores and max(scores)[0] > 0.8 else None


def parse(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    program = os.path.basename(sys.argv[0]) or 'executable'
    if not argv:
        emit_help(program, code=2)
    first = argv[0]
    if first in ('-h', '--help'):
        emit_help(program)
    if first in ('-V', '--version'):
        sys.stdout.write('rnr 0.5.1\n')
        raise SystemExit(0)
    if first == 'help':
        cmd = None
        for arg in argv[1:]:
            if cmd is None and arg in DESCRIPTIONS:
                cmd = arg
            else:
                failure(f"unrecognized subcommand '{arg}'", usage(program, cmd))
        emit_help(program, cmd)
    if first not in DESCRIPTIONS:
        if first.startswith('-'):
            tip = None
            if first.startswith('--'):
                name = first[2:].split('=')[0]
                destinations = [c for c in DESCRIPTIONS if name in {o[0] for o in option_list(c)}]
                if destinations:
                    dest = argv[1] if len(argv) > 1 and argv[1] in destinations else destinations[0]
                    tip = f"  tip: '{dest} --{name}' exists"
            failure(f"unexpected argument '{first}' found", usage(program), tip)
        match = suggest(first, list(DESCRIPTIONS) + ['help'])
        tip = f"  tip: a similar subcommand exists: '{match}'" if match else None
        failure(f"unrecognized subcommand '{first}'", usage(program), tip)
    command = first
    args = argv[1:]
    if not args:
        emit_help(program, command, 2)
    options = option_list(command)
    by_name = {o[0]: o for o in options}
    by_short = {o[1]: o for o in options if o[1]}
    opts = Options(command)

    def specific(exclude=(), add=(), required=()):
        names = list(required) + [x for x in opts.seen if x not in exclude and x not in required]
        names.extend(n for n in add if n not in names)
        return usage(program, command, [label(by_name[x]) for x in names])

    def unexpected(arg):
        match = suggest(arg[2:], by_name) if arg.startswith('--') else None
        if match:
            tip = f"  tip: a similar argument exists: '--{match}'"
            use = specific(add=[match])
        else:
            tip = f"  tip: to pass '{arg}' as a value, use '-- {arg}'" if arg.startswith('-') else None
            use = usage(program, command)
        failure(f"unexpected argument '{arg}' found", use, tip)

    def store(option, value=None, explicit=False):
        name, short, placeholder, description, choices = option
        if name == 'help':
            emit_help(program, command)
        if name in opts.seen:
            failure(f"the argument '{label(option)}' cannot be used multiple times", usage(program, command))
        if placeholder is None:
            if explicit:
                failure(f"unexpected value '{value}' for '--{name}' found; no more were expected", specific(add=[name]))
            value = True
        else:
            if value is None:
                detail = '  [possible values: ' + ', '.join(choices) + ']' if choices else None
                failure(f"a value is required for '{label(option)}' but none was supplied", detail=detail)
            if choices and value not in choices:
                match = suggest(value, choices)
                tip = f"  tip: a similar value exists: '{match}'" if match else None
                failure(f"invalid value '{value}' for '{label(option)}'", tip=tip,
                        detail='  [possible values: ' + ', '.join(choices) + ']')
            if name in ('max-depth', 'replace-limit'):
                if value == '':
                    why = 'cannot parse integer from empty string'
                elif not value.lstrip('+').isascii() or not value.lstrip('+').isdigit() or value.count('+') > 1:
                    why = 'invalid digit found in string'
                elif int(value) > 18446744073709551615:
                    why = 'number too large to fit in target type'
                else:
                    why = None
                if why:
                    failure(f"invalid value '{value}' for '{label(option)}': {why}")
                value = int(value)
        opts.values[name] = value
        opts.seen.append(name)

    i = 0
    literal = False
    while i < len(args):
        arg = args[i]
        i += 1
        if not literal and arg == '--':
            literal = True
            continue
        if not literal and arg.startswith('--'):
            name, sep, value = arg[2:].partition('=')
            if name not in by_name:
                unexpected('--' + name)
            option = by_name[name]
            if option[2] and not sep:
                if i < len(args) and (not args[i].startswith('-') or args[i] == '-'):
                    value = args[i]
                    i += 1
                else:
                    if i < len(args) and args[i].startswith('-') and len(args[i]) > 1 and not args[i].startswith('--') and args[i][1] not in by_short:
                        unexpected('-' + args[i][1])
                    value = None
            store(option, value, bool(sep))
        elif not literal and arg.startswith('-') and arg != '-':
            j = 1
            while j < len(arg):
                short = arg[j]
                j += 1
                if short not in by_short:
                    unexpected('-' + short)
                option = by_short[short]
                if option[2]:
                    if j < len(arg):
                        value = arg[j:]
                        if value.startswith('='):
                            value = value[1:]
                    elif i < len(args) and (not args[i].startswith('-') or args[i] == '-'):
                        value = args[i]
                        i += 1
                    else:
                        if i < len(args) and args[i].startswith('-') and len(args[i]) > 1 and not args[i].startswith('--') and args[i][1] not in by_short:
                            unexpected('-' + args[i][1])
                        value = None
                    store(option, value)
                    break
                else:
                    store(option)
        else:
            if command == 'from-file' and opts.positionals:
                unexpected(arg)
            opts.positionals.append(arg)
    for name in opts.seen:
        conflicts = CONFLICTS.get(name, set())
        others = [x for x in opts.seen if x in conflicts]
        if others:
            other = others[0]
            if len(others) == 1:
                conflict = "'" + label(by_name[other]) + "'"
            else:
                conflict = '\n' + ''.join('  ' + label(by_name[x]) + '\n' for x in others).rstrip('\n')
            failure(f"the argument '{label(by_name[name])}' cannot be used with {conflict}", specific(exclude=others))
    missing = []
    required = []
    min_count = len(POSITIONALS[command])
    if len(opts.positionals) < min_count:
        missing += POSITIONALS[command][len(opts.positionals):]
    if any(opts.get(x) is not False for x in ('max-depth', 'hidden')) and not opts.get('recursive'):
        missing.append('--recursive')
        required = ['recursive']
    if missing:
        failure('the following required arguments were not provided:\n' + '\n'.join('  ' + x for x in missing), specific(required=required))
    return opts
EOF"}

