"""Small, lexical POSIX path operations, without resolving symlinks or '..'."""
import os
import re


def parts(path):
    result = []
    if path.startswith('/'):
        end = len(path) - len(path.lstrip('/'))
        result.append(('/', 0, end))
    for match in re.finditer('[^/]+', path):
        value = match.group()
        if value == '.' and (result or match.start() != 0):
