    return tuple(c[0] for c in parts(path))


def split(path):
    p = parts(path)
    if not p:
        return None, None
    last = p[-1][0]
    if last == '/':
        return None, None
    parent = path[:p[-2][2]] if len(p) > 1 else ''
    return parent, None if last in ('.', '..') else last


def push(parent, child):
    if child.startswith('/'):
        return child
    if not parent:
        return child
    return parent + ('' if parent.endswith('/') else '/') + child


def replace_name(path, new_name):
    parent, name = split(path)
    return push(parent or '', new_name)


def exists(path):
    try:
        os.lstat(path)
        return True
    except (OSError, ValueError):
        return False


def descendants(parent_key, child_key):
    return len(parent_key) < len(child_key) and child_key[:len(parent_key)] == parent_key


