    """Explicit roots are always visible; symlinks are not followed below a root."""
    seen = set()

    def visit(path, depth, root):
        try:
            os.lstat(path)
        except (OSError, ValueError):
            return
        pathkey = key(path)
        if pathkey in seen:
            return
        seen.add(pathkey)
