"""Output formatting, including character-level change highlighting."""
import os
import sys
from .paths import split


def panic(line):
    sys.stderr.write(f"\nthread 'main' ({os.getpid()}) panicked at src/output.rs:{line}:" + ('49' if line in (120, 122) else '50') + ':\n'
                     'called `Option::unwrap()` on a `None` value\n'
                     'note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n')
    raise SystemExit(101)


def changes(old, new):
    """An LCS with the earliest old/new alignment breaking ties.

    Deletions are retained as events so two unchanged regions separated by a
    removed region remain independently highlighted.
    """
    n, m = len(old), len(new)
    if not n:
        return [('add', new)]
    if not m:
        return [('del', old)]
    lengths = [[0] * (m+1) for _ in range(n+1)]
    for i in range(n-1, -1, -1):
        row, below = lengths[i], lengths[i+1]
        for j in range(m-1, -1, -1):
            row[j] = below[j+1] + 1 if old[i] == new[j] else max(below[j], row[j+1])
    pairs = []
    i = j = 0
    remaining = lengths[0][0]
    while remaining:
        found = False
        for u in range(i, n):
            for v in range(j, m):
                if old[u] == new[v] and lengths[u+1][v+1] == remaining-1:
                    pairs.append((u, v))
                    i, j = u+1, v+1
                    remaining -= 1
                    found = True
                    break
            if found:
                break
    events = []

    def append(kind, text):
        if not text:
            return
        if events and events[-1][0] == kind:
            events[-1] = (kind, events[-1][1] + text)
        else:
            events.append((kind, text))

    i = j = 0
    for u, v in pairs:
        append('del', old[i:u])
        append('add', new[j:v])
        append('equal', old[u])
        i, j = u+1, v+1
    append('del', old[i:])
    append('add', new[j:])
    return events


class Output:
    def __init__(self, options):
        self.silent = options.get('silent')
        mode = options.get('color')
        self.color = mode == 'always' or (mode == 'auto' and sys.stdout.isatty())
        self.dry_run = not options.get('force')

    def paint(self, text, code):
        return f'\x1b[{code}m{text}\x1b[0m' if self.color else text

    def banner(self):
        if self.dry_run and not self.silent:
            sys.stdout.write(self.paint('This is a DRY-RUN', '1') + '\n')

    def error(self, message, detail='', unconditional=False):
        if not self.silent or unconditional:
            sys.stderr.write(self.paint('Error: ', '31') + message + self.paint(detail, '31') + '\n')
        raise SystemExit(1)

    def backup(self, source, target):
        if not self.silent:
            sys.stdout.write(self.paint('Info: ', '1') + ' Backup created - ' + self.paint(source + ' -> ' + target, '38;5;8') + '\n')

    def operation(self, source, target):
        if self.silent:
            return
        sp, sn = split(source)
        tp, tn = split(target)
        if sp is None:
            panic(120)
        if sn is None:
            panic(121)
        if tp is None:
            panic(122)
        if tn is None:
            panic(123)
        sp = sp + '/' if sp else ''
        tp = tp + '/' if tp else ''
        if not self.color:
            sys.stdout.write(sp + sn + ' -> ' + tp + tn + '\n')
            return
        text = self.paint(sp, '38;5;8') if sp else ''
        text += self.paint(sn, '38;5;8') + ' -> '
        if tp:
            text += self.paint(tp, '32')
        # Avoid a quadratic matrix for deliberately enormous replacement names.
        if len(sn) * len(tn) > 2000000:
            text += self.paint(tn, '1;31')
        else:
            for kind, value in changes(sn, tn):
                if kind != 'del':
                    text += self.paint(value, '32' if kind == 'equal' else '1;31')
        sys.stdout.write(text + '\n')
