"""Planning, validating, recording, and applying filename operations."""
import datetime
import json
import os
import shutil
import sys

from .cli import parse
from .output import Output
from . import paths
from .transliteration import to_ascii
from .regular import Regex, RegexError


def read_operations(filename, output):
    try:
        file = open(filename, 'rb')
    except IsADirectoryError:
        output.error('Cannot parse JSON file ', filename)
    except (OSError, ValueError):
        output.error('Cannot open/read file ', filename)

    def pairs(items):
        obj = {}
        for k, v in items:
            if k in obj and k in ('date', 'operations', 'source', 'target'):
                raise ValueError('duplicate field')
            obj[k] = v
        return obj

    def structure(obj, names):
        if isinstance(obj, dict):
            return [obj[name] for name in names]
        if isinstance(obj, list) and len(obj) == len(names):
            return obj
        raise ValueError('invalid structure')

    def valid_string(s):
        return isinstance(s, str) and not any(0xd800 <= ord(c) <= 0xdfff for c in s)

    try:
        with file:
            contents = file.read().decode('utf-8')
        value = json.loads(contents, object_pairs_hook=pairs,
                           parse_constant=lambda value: (_ for _ in ()).throw(ValueError(value)))
        date, ops = structure(value, ['date', 'operations'])
        if not valid_string(date) or not isinstance(ops, list):
            raise ValueError('invalid dump')
        operations = []
        for obj in ops:
            source, target = structure(obj, ['source', 'target'])
            if not valid_string(source) or not valid_string(target):
                raise ValueError('invalid paths')
            operations.append((source, target))
        return operations
    except (OSError, UnicodeError, ValueError, KeyError, TypeError, RecursionError):
        output.error('Cannot parse JSON file ', filename)


def plan_operations(options, expression, output):
    command = options.command
    sources = options.positionals[2:] if command == 'regex' else options.positionals
    operations = []
    for source in paths.targets(sources, options.get('recursive'), options.get('hidden'),
                                options.get('include-dirs'), options.get('max-depth', None)):
        parent, name = paths.split(source)
        if name is None:
            continue
        if command == 'regex':
            target_name = expression.replace(name, options.positionals[1], options.get('replace-limit'), options.get('replace-transform', None))
        else:
            target_name = to_ascii(name)
        target = paths.replace_name(source, target_name)
        if paths.key(source) != paths.key(target):
            operations.append((source, target))
    by_target = {}
    for op in operations:
        by_target.setdefault(paths.key(op[1]), []).append(op)
    conflicts = [ops for ops in by_target.values() if len(ops) > 1]
    if conflicts:
        block = ''.join(s + '->' + t + '\n' for group in conflicts for s, t in sorted(group)) + '\n'
        output.error('Files will have the same name\n\n', block)
    by_source = {paths.key(s): (s, t) for s, t in operations}
    for source, target in operations:
        if paths.key(target) not in by_source and paths.exists(target):
            output.error('Conflict with existing path ', source + ' -> ' + target)
    # Dependencies handle both occupied destinations and directories that are
    # themselves being moved.  Deepest paths are preferred among independent
    # operations, preserving child-before-parent traversal.
    operations.sort(key=lambda op: (-len(paths.key(op[0])), paths.key(op[0])))
    state = {}
    result = []
    keys = list(by_source)

    def add(sourcekey):
        status = state.get(sourcekey)
        if status == 2:
            return
        if status == 1:
            output.error('Cannot solve sorting problem.')
        state[sourcekey] = 1
        source, target = by_source[sourcekey]
        dest = paths.key(target)
        if dest in by_source:
            add(dest)
        for child in keys:
            if paths.descendants(sourcekey, child):
                add(child)
        state[sourcekey] = 2
        result.append((source, target))

    for source, _ in operations:
        add(paths.key(source))
    return result


def dump_operations(operations, prefix, output):
    now = datetime.datetime.now()
    filename = prefix + now.strftime('%Y-%m-%d_%H%M%S') + '.json'
    obj = {'date': now.strftime('%Y-%m-%d %H:%M:%S'),
           'operations': [{'source': s, 'target': t} for s, t in operations]}
    try:
        with open(filename, 'w', encoding='utf-8', newline='') as file:
            file.write(json.dumps(obj, ensure_ascii=False, indent=2))
    except (OSError, ValueError):
        output.error('Cannot create file ', filename)


def create_backup(source, output):
    if os.path.isdir(source):
        return
    target = source + '.bk'
    count = 0
    while paths.exists(target):
        count += 1
        target = source + '.bk.' + str(count)
    try:
        shutil.copyfile(source, target)
        shutil.copymode(source, target)
    except (OSError, ValueError, shutil.Error):
        output.error('Cannot create a backup of ', source)
    output.backup(source, target)


def run(options):
    output = Output(options)
    expression = None
    if options.command == 'regex':
        try:
            expression = Regex(options.positionals[0])
        except RegexError as e:
            output.error('Bad expression provided\n\n', str(e), unconditional=True)
    output.banner()
    if options.command == 'from-file':
        operations = read_operations(options.positionals[0], output)
        if options.get('undo'):
            operations = [(target, source) for source, target in reversed(operations)]
    else:
        operations = plan_operations(options, expression, output)
    if not options.get('no-dump') and (options.get('force') or options.get('dump')):
        dump_operations(operations, options.get('dump-prefix'), output)
    for source, target in operations:
        if options.get('force'):
            if options.get('backup'):
                create_backup(source, output)
            try:
                os.rename(source, target)
            except (OSError, ValueError) as e:
                reason = (os.strerror(e.errno) + f' (os error {e.errno})') if isinstance(e, OSError) else 'file name contained an unexpected NUL byte'
                output.error('Cannot rename ', source + ' -> ' + target + '\n' + reason)
        output.operation(source, target)


def main():
    try:
        run(parse())
    except BrokenPipeError:
        try:
            sys.stdout.close()
        except OSError:
            pass
        raise SystemExit(1)
