                            self.fail('unclosed group', start, start+1)
                        ending = self.text[self.i]
                        self.i += 1
                        if ending == ')':
                            flags = changed
                            continue
                        self.depth += 1
                        if self.depth > 250:
                            self.fail('exceed the maximum number of nested parentheses/brackets (250)', start, start+1)
                        value = self.parse(changed, start)
                        self.depth -= 1
                        tokens.append('(?:' + value + ')')
                        have_atom = True
                        continue
                if group_kind == 'capture':
                    self.groups += 1
                self.depth += 1
                if self.depth > 250:
                    self.fail('exceed the maximum number of nested parentheses/brackets (250)', start, start+1)
                value = self.parse(flags, start)
                self.depth -= 1
                tokens.append(('(' if group_kind == 'capture' else '(?:') + value + ')')
            elif c == '[':
                bits = self.charset(flags)
                if 'u' not in flags and bits & ~ASCII:
                    self.fail('pattern can match invalid UTF-8', start, self.i)
                tokens.append(self.case(class_string(bits), flags))
            elif c == '\\':
                value, ischar = self.escape(flags, False)
                if ischar:
                    tokens.append(self.case(re.escape(chr(value)), flags))
                elif isinstance(value, int):
                    if 'u' not in flags and value & ~ASCII:
                        self.fail('pattern can match invalid UTF-8', start, self.i)
                    tokens.append(self.case(class_string(value), flags))
                else:
                    tokens.append(value)
            elif c == '.':
                self.i += 1
                if 'u' not in flags:
                    self.fail('pattern can match invalid UTF-8', start, self.i)
                tokens.append('[\\s\\S]' if 's' in flags else ('[^\r\n]' if 'R' in flags else '[^\n]'))
            elif c == '^':
                self.i += 1
                if 'm' in flags:
                    tokens.append('(?m:^)' if 'R' not in flags else '(?:\\A|(?<=\n)|(?<=\r)(?!\n))')
                else:
                    tokens.append('\\A')
            elif c == '$':
                self.i += 1
                if 'm' in flags:
                    tokens.append('(?m:$)' if 'R' not in flags else '(?:\\Z|(?=\r)|(?<!\r)(?=\n))')
                else:
                    tokens.append('\\Z')
            else:
                self.i += 1
                tokens.append(self.case(re.escape(c), flags))
            have_atom = True
        return ''.join(tokens)

    def escape(self, flags, in_class):
        start = self.i
        self.i += 1
        if self.i >= len(self.text):
            self.fail('incomplete escape sequence, reached end of pattern prematurely', start, self.i)
        c = self.text[self.i]
        self.i += 1
        if c in '0123456789':
            self.fail('backreferences are not supported', start, self.i)
        if c in 'dDsSwW':
            return perl_bits(c, 'u' in flags), False
        if c in 'pP':
            if self.i >= len(self.text):
                self.fail('incomplete escape sequence, reached end of pattern prematurely', start, self.i)
            if self.text[self.i] == '{':
                self.i += 1
                close = self.text.find('}', self.i)
                if close < 0:
                    self.fail('unclosed Unicode character class', start, len(self.text))
                name = self.text[self.i:close]
                self.i = close+1
            else:
                name = self.text[self.i]
                self.i += 1
            if 'u' not in flags:
                self.fail('Unicode not allowed here', start, self.i)
            bits = property_bits(name)
            if bits is None:
                self.fail('Unicode property not found', start, self.i)
            return (SCALARS ^ bits if c == 'P' else bits), False
        if c in 'xuU':
            if self.i < len(self.text) and self.text[self.i] == '{':
                self.i += 1
                digits = self.i
                while self.i < len(self.text) and self.text[self.i] != '}':
                    if self.text[self.i] not in '0123456789abcdefABCDEF':
                        self.fail('invalid hexadecimal digit', self.i, self.i+1)
                    self.i += 1
                if self.i == len(self.text):
                    self.fail('unclosed hexadecimal literal', start, self.i)
                if self.i == digits:
                    self.fail('empty hexadecimal literal', digits, self.i+1)
                value = int(self.text[digits:self.i], 16)
                self.i += 1
            else:
                count = {'x': 2, 'u': 4, 'U': 8}[c]
                digits = self.i
                for _ in range(count):
                    if self.i >= len(self.text):
                        self.fail('incomplete escape sequence, reached end of pattern prematurely', start, self.i)
                    if self.text[self.i] not in '0123456789abcdefABCDEF':
                        self.fail('invalid hexadecimal digit', self.i, self.i+1)
                    self.i += 1
                value = int(self.text[digits:self.i], 16)
            if value >= MAX_CHAR or 0xd800 <= value <= 0xdfff:
                self.fail('hexadecimal literal is not a Unicode scalar value', start, self.i)
            if 'u' not in flags and value > 127:
                self.fail('pattern can match invalid UTF-8', start, self.i)
            return value, True
        escapes = {'a': '\a', 'f': '\f', 't': '\t', 'n': '\n', 'r': '\r', 'v': '\v'}
        if c in escapes:
            return ord(escapes[c]), True
        if not in_class and c in ('A', 'z'):
            return ('\\A' if c == 'A' else '\\Z'), False
        if not in_class and c in ('b', 'B'):
            word = class_string(perl_bits('w', 'u' in flags))
            if c == 'b':
                return '(?:(?<!' + word + ')(?=' + word + ')|(?<=' + word + ')(?!' + word + '))', False
            return '(?:(?<=' + word + ')(?=' + word + ')|(?<!' + word + ')(?!' + word + '))', False
        if not c.isalnum() and c.isascii():
            return ord(c), True
        self.fail('unrecognized escape sequence', start, self.i)

    def charset(self, flags):
        opening = self.i
        self.i += 1
        self.skip(flags)
        invert = self.i < len(self.text) and self.text[self.i] == '^'
        if invert:
            self.i += 1
        accum = None
        current = 0
        op = None
        first = True

        def combine(a, b, operator):
            if a is None:
                return b
            if operator == '&&':
                return a & b
            if operator == '--':
                return a & ~b
            if operator == '~~':
                return a ^ b
            return a | b

        while True:
            self.skip(flags)
            if self.i >= len(self.text):
                self.fail('unclosed character class', opening, opening + (2 if self.text[opening:] == '[]' else 1))
            if self.text[self.i] == ']' and not first:
                self.i += 1
                current = combine(accum, current, op)
                return SCALARS ^ current if invert else current
            operation = self.text[self.i:self.i+2]
            if operation in ('&&', '--', '~~') and not first:
                accum = combine(accum, current, op)
                current = 0
                op = operation
                self.i += 2
                first = True
                continue
            atom_start = self.i
            bits, scalar = self.class_atom(flags)
            first = False
            self.skip(flags)
            if (scalar is not None and self.i < len(self.text) and self.text[self.i] == '-'
                    and not self.text.startswith('--', self.i)
                    and self.i+1 < len(self.text) and self.text[self.i+1] != ']'):
                self.i += 1
                self.skip(flags)
                endbits, endscalar = self.class_atom(flags)
                if endscalar is None:
                    self.fail('invalid range boundary, must be a literal', atom_start, self.i)
                if scalar > endscalar:
                    self.fail('invalid character class range, the start must be <= the end', atom_start, self.i)
                bits = interval(scalar, endscalar)
            current |= bits

    def class_atom(self, flags):
        if self.i >= len(self.text):
            self.fail('unclosed character class', max(0, self.i-1), self.i)
        start = self.i
        c = self.text[self.i]
        if self.text.startswith('[:', self.i):
            close = self.text.find(':]', self.i+2)
            if close >= 0:
                name = self.text[self.i+2:close]
                bits = posix_bits(name)
                if bits is None:
                    self.fail('invalid ASCII character class', start, close+2)
                self.i = close+2
                return bits, None
        if c == '[':
            return self.charset(flags), None
        if c == '\\':
            value, scalar = self.escape(flags, True)
            return ((1 << value), value) if scalar else (value, None)
        self.i += 1
        return 1 << ord(c), ord(c)


class Regex:
    def __init__(self, pattern):
        parser = Parser(pattern)
        translated = parser.parse()
        self.names = parser.names
        try:
            self.compiled = re.compile(translated)
        except (re.error, OverflowError, RecursionError) as error:
            raise RegexError(pattern, 0, max(1, len(pattern)), str(error))

    def expansion(self, replacement, match):
        pieces = []
        i = 0
        while i < len(replacement):
            if replacement[i] != '$':
                pieces.append(replacement[i])
                i += 1
                continue
            if i+1 < len(replacement) and replacement[i+1] == '$':
                pieces.append('$')
                i += 2
                continue
            end = i+1
            if end < len(replacement) and replacement[end] == '{':
                close = replacement.find('}', end+1)
                if close < 0:
                    pieces.append('$')
                    i += 1
                    continue
                name = replacement[end+1:close]
                end = close+1
            else:
                while end < len(replacement) and replacement[end] in '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_':
                    end += 1
                if end == i+1:
                    pieces.append('$')
                    i += 1
                    continue
                name = replacement[i+1:end]
            group = int(name) if name and name.isascii() and name.isdigit() else self.names.get(name)
            if group is not None:
                try:
                    pieces.append(match.group(group) or '')
                except (IndexError, OverflowError):
                    pass
            i = end
        return ''.join(pieces)

    def replace(self, text, replacement, limit, transform=None):
        pieces = []
        last = 0
        pos = 0
        previous_end = None
        count = 0
        while pos <= len(text) and (not limit or count < limit):
            match = self.compiled.search(text, pos)
            if match is None:
                break
            start, end = match.span()
            if start == end and end == previous_end:
                pos = end+1
                continue
            pieces.append(text[last:start])
            value = self.expansion(replacement, match)
            if transform == 'upper':
                value = value.upper()
            elif transform == 'lower':
                value = value.lower()
            elif transform == 'ascii':
                value = to_ascii(value)
            pieces.append(value)
            last = end
            previous_end = end
            pos = end+1 if start == end else end
            count += 1
        if not count:
            return text
        pieces.append(text[last:])
        return ''.join(pieces)
