"""A regular-expression dialect adapter and capture replacement interpreter.

The parser deliberately accepts only regular constructs.  Matching is provided
by the standard library after groups, flags, Unicode sets, and anchors have
been translated.  In particular, backreferences and look-around in user input
are rejected rather than accidentally acquiring Python-specific behavior.
"""
import functools
import re
import unicodedata
from .transliteration import to_ascii

MAX_CHAR = 0x110000
ALL = (1 << MAX_CHAR) - 1
SCALARS = ALL ^ (((1 << 0x800) - 1) << 0xd800)
ASCII = (1 << 128) - 1


def interval(a, b):
    return ((1 << (b-a+1)) - 1) << a if a <= b else 0


def members(values):
    value = 0
    for c in values:
        value |= 1 << ord(c)
    return value


SPACE = interval(9, 13) | members(' \x85\xa0\u1680\u2028\u2029\u202f\u205f\u3000') | interval(0x2000, 0x200a)
CATEGORIES = {
    'letter': 'L', 'casedletter': 'LC', 'uppercaseletter': 'Lu', 'lowercaseletter': 'Ll', 'titlecaseletter': 'Lt', 'modifierletter': 'Lm', 'otherletter': 'Lo',
    'mark': 'M', 'nonspacingmark': 'Mn', 'spacingmark': 'Mc', 'spacingcombiningmark': 'Mc', 'enclosingmark': 'Me',
    'number': 'N', 'decimalnumber': 'Nd', 'decimaldigitnumber': 'Nd', 'letternumber': 'Nl', 'othernumber': 'No',
    'punctuation': 'P', 'connectorpunctuation': 'Pc', 'dashpunctuation': 'Pd', 'openpunctuation': 'Ps', 'closepunctuation': 'Pe', 'initialpunctuation': 'Pi', 'finalpunctuation': 'Pf', 'otherpunctuation': 'Po',
    'symbol': 'S', 'mathsymbol': 'Sm', 'currencysymbol': 'Sc', 'modifiersymbol': 'Sk', 'othersymbol': 'So',
    'separator': 'Z', 'spaceseparator': 'Zs', 'lineseparator': 'Zl', 'paragraphseparator': 'Zp',
    'other': 'C', 'control': 'Cc', 'format': 'Cf', 'surrogate': 'Cs', 'privateuse': 'Co', 'unassigned': 'Cn',
}
CAT_CODES = {'L','Lu','Ll','Lt','Lm','Lo','LC','M','Mn','Mc','Me','N','Nd','Nl','No','P','Pc','Pd','Ps','Pe','Pi','Pf','Po','S','Sm','Sc','Sk','So','Z','Zs','Zl','Zp','C','Cc','Cf','Cs','Co','Cn'}
SCRIPTS = {
    'latin': 'LATIN', 'latn': 'LATIN', 'greek': 'GREEK', 'grek': 'GREEK', 'cyrillic': 'CYRILLIC', 'cyrl': 'CYRILLIC',
    'hebrew': 'HEBREW', 'hebr': 'HEBREW', 'arabic': 'ARABIC', 'arab': 'ARABIC', 'armenian': 'ARMENIAN', 'armn': 'ARMENIAN',
    'georgian': 'GEORGIAN', 'geor': 'GEORGIAN', 'devanagari': 'DEVANAGARI', 'deva': 'DEVANAGARI',
    'bengali': 'BENGALI', 'beng': 'BENGALI', 'gurmukhi': 'GURMUKHI', 'gujarati': 'GUJARATI',
    'tamil': 'TAMIL', 'telugu': 'TELUGU', 'malayalam': 'MALAYALAM', 'kannada': 'KANNADA',
    'thai': 'THAI', 'lao': 'LAO', 'tibetan': 'TIBETAN', 'myanmar': 'MYANMAR', 'ethiopic': 'ETHIOPIC',
    'hiragana': 'HIRAGANA', 'hira': 'HIRAGANA', 'katakana': 'KATAKANA', 'kana': 'KATAKANA',
    'hangul': 'HANGUL', 'hang': 'HANGUL', 'han': 'CJK', 'hani': 'CJK', 'bopomofo': 'BOPOMOFO',
    'cherokee': 'CHEROKEE', 'ogham': 'OGHAM', 'runic': 'RUNIC', 'khmer': 'KHMER', 'mongolian': 'MONGOLIAN',
}


def bit_predicate(predicate):
    result = 0
    start = None
    for i in range(MAX_CHAR):
        ok = not 0xd800 <= i <= 0xdfff and predicate(chr(i))
        if ok and start is None:
            start = i
        elif not ok and start is not None:
            result |= interval(start, i-1)
            start = None
    if start is not None:
        result |= interval(start, MAX_CHAR-1)
    return result


@functools.lru_cache(maxsize=64)
def property_bits(name):
    normalized = re.sub(r'[_\-\s]', '', name).lower()
    negate = False
    if '!=' in normalized:
        prefix, normalized = normalized.split('!=', 1)
        negate = True
    elif '=' in normalized or ':' in normalized:
        prefix, normalized = re.split('[=:]', normalized, 1)
    else:
        prefix = ''
    if prefix and prefix not in ('gc', 'generalcategory', 'sc', 'script', 'scx', 'scriptextensions'):
        return None
    if normalized.startswith('is') and normalized[2:] in SCRIPTS:
        normalized = normalized[2:]
    code = CATEGORIES.get(normalized)
    if code is None:
        code = next((c for c in CAT_CODES if c.lower() == normalized), None)
    if code:
        if code == 'LC':
            value = bit_predicate(lambda c: unicodedata.category(c) in ('Lu', 'Ll', 'Lt'))
        else:
            value = bit_predicate(lambda c: unicodedata.category(c).startswith(code))
    elif normalized in ('any',):
        value = SCALARS
    elif normalized in ('ascii',):
        value = ASCII
    elif normalized in ('assigned',):
        value = bit_predicate(lambda c: unicodedata.category(c) != 'Cn')
    elif normalized in ('whitespace', 'space', 'wspace'):
        value = SPACE
    elif normalized in ('word',):
        value = bit_predicate(lambda c: c.isalpha() or unicodedata.category(c)[0] == 'M' or unicodedata.category(c) in ('Nd', 'Nl', 'Pc') or c in '\u200c\u200d')
    elif normalized in ('alphabetic', 'alpha'):
        value = bit_predicate(lambda c: c.isalpha() or unicodedata.category(c) == 'Nl')
    elif normalized in ('lowercase', 'lower'):
        value = bit_predicate(str.islower)
    elif normalized in ('uppercase', 'upper'):
        value = bit_predicate(str.isupper)
    elif normalized == 'alphanumeric':
        value = bit_predicate(str.isalnum)
    elif normalized in ('joincontrol',):
        value = members('\u200c\u200d')
    elif normalized in ('asciihexdigit', 'ahex'):
        value = members('0123456789abcdefABCDEF')
    elif normalized in ('hexdigit', 'hex'):
        value = members('0123456789abcdefABCDEF０１２３４５６７８９ａｂｃｄｅｆＡＢＣＤＥＦ')
    elif normalized in ('dash',):
        value = property_bits('Pd') | members('⁓∼')
    elif normalized in ('math',):
        value = property_bits('Sm')
    elif normalized in SCRIPTS:
        prefix_name = SCRIPTS[normalized]
        value = bit_predicate(lambda c: unicodedata.name(c, '').startswith(prefix_name))
        if prefix_name == 'CJK':
            value |= members('々〇〡〢〣〤〥〦〧〨〩〻')
    else:
        return None
    return (SCALARS ^ value) if negate else value


@functools.lru_cache(maxsize=256)
def class_string(bits):
    if not bits:
        return '(?!)'
    result = []
    while bits:
        start = (bits & -bits).bit_length() - 1
        shifted = bits >> start
        count = (shifted ^ (shifted+1)).bit_length() - 1
        end = start + count - 1
        def escape(c):
            return f'\\u{c:04x}' if c <= 0xffff else f'\\U{c:08x}'
        result.append(escape(start) if end == start else escape(start) + '-' + escape(end))
        bits ^= interval(start, end)
    return '[' + ''.join(result) + ']'


def perl_bits(kind, unicode):
    if kind.lower() == 'd':
        value = property_bits('Nd') if unicode else interval(48, 57)
    elif kind.lower() == 's':
        value = SPACE if unicode else members(' \t\n\r\v\f')
    else:
        value = property_bits('word') if unicode else interval(65, 90) | interval(97, 122) | interval(48, 57) | members('_')
    return (SCALARS ^ value) if kind.isupper() else value


def posix_bits(name):
    neg = name.startswith('^')
    if neg:
        name = name[1:]
    lower = interval(97, 122)
    upper = interval(65, 90)
    digit = interval(48, 57)
    classes = {
        'alnum': lower | upper | digit, 'alpha': lower | upper, 'ascii': ASCII,
        'blank': members(' \t'), 'cntrl': interval(0, 31) | (1 << 127),
        'digit': digit, 'graph': interval(33, 126), 'lower': lower,
        'print': interval(32, 126), 'punct': interval(33, 126) ^ (lower | upper | digit),
        'space': members(' \t\n\r\v\f'), 'upper': upper,
        'word': lower | upper | digit | members('_'), 'xdigit': digit | members('abcdefABCDEF'),
    }
    if name not in classes:
        return None
    return SCALARS ^ classes[name] if neg else classes[name]


class RegexError(Exception):
    def __init__(self, pattern, start=0, end=None, message='', extra=None, raw=None):
        if raw is not None:
            self.text = raw
        elif '\n' not in pattern:
            end = start+1 if end is None else end
            spans = [(start, max(start+1, end))] + (extra or [])
            caret = [' '] * max(e for s, e in spans)
            for a, b in spans:
                caret[a:b] = ['^'] * (b-a)
            self.text = 'regex parse error:\n    ' + pattern + '\n    ' + ''.join(caret).rstrip() + '\nerror: ' + message
        else:
            # Multiline patterns get a numbered excerpt, preserving whitespace.
            lines = pattern.split('\n')
            width = len(str(len(lines)))
            body = []
            offset = 0
            for n, line in enumerate(lines, 1):
                body.append(f'{n:>{width}}: {line}')
                if offset <= start <= offset+len(line):
                    body.append(' ' * (width+2+start-offset) + '^' * max(1, (end or start+1)-start))
                offset += len(line)+1
            self.text = 'regex parse error:\n' + '\n'.join(body) + '\nerror: ' + message
        super().__init__(self.text)

    def __str__(self):
        return self.text


class Parser:
    def __init__(self, pattern):
        self.text = pattern
        self.i = 0
        self.groups = 0
        self.names = {}
        self.name_positions = {}
        self.depth = 0

    def fail(self, msg, start=None, end=None, extra=None):
        raise RegexError(self.text, self.i if start is None else start, end, msg, extra)

    def skip(self, flags):
        if 'x' in flags:
            while self.i < len(self.text):
