                    while self.i < len(self.text) and self.text[self.i] in '0123456789':
                        self.i += 1
                    if self.i == digit_start:
                        self.fail('repetition quantifier expects a valid decimal', self.i, self.i+1)
                    low = int(self.text[digit_start:self.i])
                    high = low
                    if self.i < len(self.text) and self.text[self.i] == ',':
                        self.i += 1
                        digit_start = self.i
                        while self.i < len(self.text) and self.text[self.i] in '0123456789':
                            self.i += 1
                        high = int(self.text[digit_start:self.i]) if self.i > digit_start else None
                    if self.i >= len(self.text):
                        self.fail('unclosed counted repetition', start, self.i)
                    if self.text[self.i] != '}':
                        self.fail('unclosed counted repetition', start, self.i)
                    self.i += 1
                    if high is not None and low > high:
                        self.fail('invalid repetition count range, the start must be <= the end', start, self.i)
                    if low > 1000000 or (high is not None and high > 1000000):
